    import sys
    class __S(object):
        def __init__(self):
            self.io = sys.stdin
            self.nm = sys.maxint
            self.buf = self.line = None
            self.ln = 0
        def __iter__(self):
            return self
        def __next__(self):
            return self.readline()
        def readline(self):
            if self.line is None:
                self.line = self.io.readline()
            if self.line == '':
                raise StopIteration
            buf = self.line
            self.line = None
            return buf
        def bufferline(self):
            if self.buf is None:
                self.buf = self.io.read()
            lines = self.buf.splitlines()
            if self.ln >= len(lines):
                raise StopIteration
